SELECT rec_id AS id, "Tên hồ sơ" AS title, "Mã hồ sơ" AS code, "Brand" AS brand, "Trạng thái" AS status, "Người lập ID" AS creator, CURRENT_USER_ID() AS actor_id, "Thời gian lập" AS created_at, "Bảng tính nguồn" AS sheet_url, "Người duyệt đề xuất JSON" AS approvers, "Bản tiền JSON" AS snapshot, "Tổng tiền trình" AS total, "Số dòng" AS count, "Luồng duyệt JSON" AS nodes, "Lịch sử duyệt JSON" AS audit, "Kết quả đồng bộ JSON" AS sync_results, "Bản chốt SHA256" AS hash, "Phiên xử lý" AS version FROM "A03. Hồ sơ trình duyệt" WHERE ("Người lập ID" = CURRENT_USER_ID() OR ("Người duyệt 1").id = CURRENT_USER_ID() OR ("Người duyệt 2").id = CURRENT_USER_ID() OR ("Người duyệt 3").id = CURRENT_USER_ID() OR ("Người duyệt 4").id = CURRENT_USER_ID() OR ("Người duyệt 5").id = CURRENT_USER_ID()) ORDER BY rec_id DESC LIMIT 50
